import React from 'react';
import {  } from 'lucide-react';

const MyApplications = () => {
  const applications = [
    { id: 1, company: "Tech Solutions", date: "2026-04-20", status: "مقبول" },
    { id: 2, company: "DigiArt", date: "2026-04-22", status: "قيد الانتظار" }
  ];

  const getStatusStyle = (status) => {
    if (status === "مقبول") return "bg-green-50 text-green-700 border-green-100";
    if (status === "مرفوض") return "bg-red-50 text-red-700 border-red-100";
    return "bg-amber-50 text-amber-700 border-amber-100";
  };

  return (
    <div className="p-6 max-w-4xl mx-auto" dir="rtl">
      <h1 className="text-2xl font-bold mb-6">طلبات التقديم الخاصة بي</h1>
      <div className="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-sm">
        <table className="w-full text-right">
          <thead className="bg-slate-50 border-b border-slate-100">
            <tr>
              <th className="p-4 font-bold text-slate-600">الشركة</th>
              <th className="p-4 font-bold text-slate-600">التاريخ</th>
              <th className="p-4 font-bold text-slate-600">الحالة</th>
            </tr>
          </thead>
          <tbody>
            {applications.map(app => (
              <tr key={app.id} className="border-b border-slate-50 last:border-none">
                <td className="p-4 font-medium">{app.company}</td>
                <td className="p-4 text-slate-500 text-sm">{app.date}</td>
                <td className="p-4">
                  <span className={`px-3 py-1 rounded-full text-xs font-bold border ${getStatusStyle(app.status)}`}>
                    {app.status}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default MyApplications;
